fn set_frame_protected(state: &mut LuaState) -> LuaResult<u32> {
    let name = String::from_stack(state, 1)?;
    let v = bool::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(id) = st.widgets.get_id_by_name(&name) {
        if let Some(frame) = st.widgets.get_mut(id) {
            frame.is_protected = v;
        }
    }
    Ok(0)
}

// ── Casting & cooldowns ──────────────────────────────────────────────────────

fn set_casting(state: &mut LuaState) -> LuaResult<u32> {
    let spell_id = u32::from_stack(state, 1)?;
    let spell_name = String::from_stack(state, 2)?;
    let icon_path = String::from_stack(state, 3)?;
    let duration = f64::from_stack(state, 4)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    let cast_id = st.next_cast_id;
    st.next_cast_id += 1;
    st.casting = Some(CastingState {
        spell_id,
        spell_name,
        icon_path,
        start_time: now,
        end_time: now + duration,
        cast_id,
    });
    Ok(0)
}

fn stop_casting(state: &mut LuaState) -> LuaResult<u32> {
    borrow_state_mut(state)?.casting = None;
    Ok(0)
}

fn set_gcd(state: &mut LuaState) -> LuaResult<u32> {
    let duration = f64::from_stack(state, 1)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    st.gcd = Some((now, duration));
    Ok(0)
}

fn set_spell_cooldown(state: &mut LuaState) -> LuaResult<u32> {
    let spell_id = u32::from_stack(state, 1)?;
    let duration = f64::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    st.spell_cooldowns.insert(
        spell_id,
        SpellCooldownState {
            start: now,
            duration,
        },
    );
    Ok(0)
}

// ── Health & power ───────────────────────────────────────────────────────────

fn set_player_health(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    st.player.health = cur;
    st.player.health_max = max;
    Ok(0)
}

fn set_player_power(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let power_type = Option::<i32>::from_stack(state, 3)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(pt) = power_type {
        if is_secondary_player_power_type(pt) {
            st.player
                .secondary_powers
                .insert(pt, SecondaryPowerState { current: cur, max });
            return Ok(0);
        }
        st.player.power_type = pt;
    }
    st.player.power = cur;
    st.player.power_max = max;
    Ok(0)
}

fn is_secondary_player_power_type(power_type: i32) -> bool {
    matches!(
        power_type,
        4 | 5 | 6 | 7 | 8 | 9 | 11 | 12 | 13 | 16 | 17 | 18
    )
}

fn set_target_health(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(t) = st.current_target.as_mut() {
        t.health = cur;
        t.health_max = max;
    }
    Ok(0)
}

