// ── Party ─────────────────────────────────────────────────────────────────────

fn set_party_size(state: &mut LuaState) -> LuaResult<u32> {
    use crate::event::Event;

    let n = i32::from_stack(state, 1)?;
    let size = n.max(0) as usize;
    let mut st = borrow_state_mut(state)?;
    let changed = st.party_members.len() != size;
    while st.party_members.len() < size {
        st.party_members.push(default_party_member());
    }
    st.party_members.truncate(size);
    st.party_group_active = size > 0;
    if changed {
        // Match the mlua admin_api: fire GROUP_ROSTER_UPDATE so
        // `PartyFrameMixin:OnEvent` runs its `self:Layout()` pass and
        // `PartyFrame:ShouldShow()` flips to true (UnitExists("party1"),
        // GetNumGroupMembers, IsInGroup all read state.party_members).
        // Without this, UpdatePartyFrames sees zero active members and
        // the frame stays at its XML 4x2 placeholder.
        st.events.push(Event {
            name: "GROUP_ROSTER_UPDATE".to_string(),
            args: Vec::new(),
        });
    }
    Ok(0)
}

fn set_party_member(state: &mut LuaState) -> LuaResult<u32> {
    let idx = i32::from_stack(state, 1)?;
    let name = String::from_stack(state, 2)?;
    let class_index = i32::from_stack(state, 3)?;
    let level = i32::from_stack(state, 4)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(member) = st.party_members.get_mut((idx - 1) as usize) {
        member.name = name;
        member.class_index = class_index;
        member.level = level;
    }
    Ok(0)
}

fn set_party_member_health(state: &mut LuaState) -> LuaResult<u32> {
    let idx = i32::from_stack(state, 1)?;
    let cur = i32::from_stack(state, 2)?;
    let max = i32::from_stack(state, 3)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(member) = st.party_members.get_mut((idx - 1) as usize) {
        member.health = cur;
        member.health_max = max;
    }
    Ok(0)
}

fn kill_party_member(state: &mut LuaState) -> LuaResult<u32> {
    let idx = i32::from_stack(state, 1)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(member) = st.party_members.get_mut((idx - 1) as usize) {
        member.dead_since = Some(std::time::Instant::now());
    }
    Ok(0)
}

fn res_party_member(state: &mut LuaState) -> LuaResult<u32> {
    let idx = i32::from_stack(state, 1)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(member) = st.party_members.get_mut((idx - 1) as usize) {
        member.dead_since = None;
    }
    Ok(0)
}

fn set_rot_damage(state: &mut LuaState) -> LuaResult<u32> {
    let level = i32::from_stack(state, 1)?;
    borrow_state_mut(state)?.rot_damage_level = level as usize;
    Ok(0)
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/// Build an AuraInfo for admin-added buffs.
pub(super) fn build_admin_buff(
    st: &crate::lua_api::state::SimState,
    spell_id: i32,
    name: String,
    icon: String,
    duration: f64,
    stacks: i32,
) -> AuraInfo {
    let expiration_time = if duration > 0.0 {
        st.start_time.elapsed().as_secs_f64() + duration
    } else {
        0.0
    };
    AuraInfo {
        name,
        spell_id,
        icon: icon.parse::<i32>().unwrap_or(0),
        duration,
        expiration_time,
        applications: stacks,
        source_unit: "player".to_string(),
        is_helpful: true,
        is_stealable: false,
        can_apply_aura: true,
        is_from_player_or_player_pet: true,
        aura_instance_id: (st.player.buffs.len() + 1) as i32,
    }
}

/// Build a MailMessage for admin inbox functions.
pub(crate) fn build_mail(
    id: u64,
    sender: String,
    subject: String,
    body: String,
    money: u64,
    items: Vec<crate::lua_api::state_types::MailAttachment>,
) -> crate::lua_api::state_types::MailMessage {
    crate::lua_api::state_types::MailMessage {
        id,
        sender,
        subject,
        body,
        money,
        cod_amount: 0,
        items,
        days_left: 30.0,
        was_read: false,
        was_returned: false,
        can_reply: true,
        is_gm: false,
        stationery_icon: 0,
    }
}

/// Convert a rilua `Val` to an `EventArg`.
pub(super) fn lua_val_to_event_arg(state: &LuaState, val: Val) -> crate::event::EventArg {
    use crate::event::EventArg;
    match val {
        Val::Str(s) => {
            let text = state
                .gc
                .string_arena
                .get(s)
                .map(|ls| String::from_utf8_lossy(ls.data()).into_owned())
                .unwrap_or_default();
            EventArg::String(text)
        }
        Val::Num(n) => EventArg::Number(n),
        Val::Bool(b) => EventArg::Boolean(b),
        _ => EventArg::Nil,
    }
}

/// Extract a string from the stack, returning a default if nil or absent.
pub(super) fn opt_string_stack(state: &LuaState, index: i32, default: &str) -> String {
    match crate::lua_bridge::stack_val(state, index) {
        Val::Str(s) => state
            .gc
            .string_arena
            .get(s)
            .map(|ls| String::from_utf8_lossy(ls.data()).into_owned())
            .unwrap_or_else(|| default.to_string()),
        _ => default.to_string(),
    }
}
